package dev.kuan.kuanperion.automation.pest;
import dev.kuan.kuanperion.automation.*;import java.util.*;
public final class PestExchangeTaskTest {
 static final long S=1_000_000_000L;static final ItemSnapshot AIR=PestExchangeViewTest.AIR,TOOL=new ItemSnapshot("INFINI_VACUUM","minecraft:golden_hoe","tool-uuid","Vacuum","tool-meta",1,List.of("Ability: Vacuum RIGHT CLICK","within 10 blocks"),true);
 static void check(boolean v,String m){if(!v)throw new AssertionError(m);}
 static class P implements PestExchangeTask.Port {
  AutomationContext ctx=new AutomationContext(1,true,true,Set.of());final AutomationCoordinator coordinator=new AutomationCoordinator();final AutomationSession session=new AutomationSession(coordinator,()->ctx,()->{},()->{});final AutomationSession.Handle owner=session.begin(AutomationFeature.PEST,0,120*S);
  final InventoryReceipts items=new InventoryReceipts();final CursorReceipts cursors=new CursorReceipts();final Object level=new Object();Object identity=new Object();long now=S;Map<Integer,ItemSnapshot> inv=new HashMap<>();MenuSnapshot menu;ItemSnapshot cursor=AIR,marker;boolean manual,failOpen,uncertain;int opens,clicks,closes;Runnable onOpen=()->{},onSend=()->{},onClose=()->{};java.util.function.Supplier<AutomationContext> read=()->ctx;
  P(){for(int i=0;i<43;i++)inv.put(i,AIR);inv.put(3,TOOL);}
  public AutomationContext context(){return read.get();}public boolean manualInput(){return manual;}
  public PestExchangeTask.Frame exchangeFrame(long time){return new PestExchangeTask.Frame(1,time,level,menu==null?null:identity,menu,inv,cursor,3);}
  public boolean openExchange(AutomationSession.Handle h,long time){opens++;onOpen.run();return !failOpen;}
  public GuardedMenuAction.Result exchangeClick(AutomationSession.Handle h,PestExchangeTask.Action a,long time){check(a.kind()==PestExchangeTask.Kind.CLICK&&a.claim(h,exchangeFrame(time),time)&&!a.claim(h,exchangeFrame(time),time),"one-use private source-role input");clicks++;onSend.run();return uncertain?GuardedMenuAction.Result.UNCERTAIN:GuardedMenuAction.Result.SENT;}
  public boolean closeExchange(AutomationSession.Handle h,PestExchangeTask.Action a,long time){onClose.run();if(!a.claim(h,exchangeFrame(time),time))return false;check(a.kind()==PestExchangeTask.Kind.CLOSE&&!a.claim(h,exchangeFrame(time),time),"one-use exact settled close");closes++;menu=null;ctx=new AutomationContext(1,true,true,Set.of());return true;}
  void refresh(){var slots=new ArrayList<MenuSnapshot.Slot>();for(int i=0;i<27;i++)slots.add(new MenuSnapshot.Slot(i,i==13?marker:AIR));for(int i=0;i<36;i++)slots.add(new MenuSnapshot.Slot(i+27,inv.get(i<27?i+9:i-27),true));menu=new MenuSnapshot(1,7,1,"Pesthunter",27,slots);}
  void show(boolean skipped,boolean receipt){now+=S;marker=PestExchangeViewTest.role(skipped?"You have exchanged enough Pests recently!":"Click to empty your Vacuum Bag!");refresh();ctx=new AutomationContext(1,true,true,Set.of(AutomationContext.Blocker.MENU));if(receipt){for(var slot:menu.slots())items.observe(1,7,slot.index(),slot.item());cursors.observe(1,7,AIR,now);}}
  void ack(boolean receipt,boolean cursorReceipt){now+=S;marker=PestExchangeViewTest.role("You have exchanged enough Pests recently!");refresh();if(receipt)items.observe(1,7,13,marker);if(cursorReceipt)cursors.observe(1,7,cursor,now);}
 }
 static PestExchangeTask begin(P p){var t=new PestExchangeTask(p.session,p.coordinator,p.items,p.cursors,p);check(!t.begin(p.owner,false,new PestIdentity.Vacuum(3,TOOL,10),p.now),"original root alone is no consent");check(t.begin(p.owner,true,new PestIdentity.Vacuum(3,TOOL,10),p.now),"authorized source route begins on original root");return t;}
 static void ready(P p,PestExchangeTask t){t.tick(p.now);check(p.opens==1,"one fixed opener");p.show(false,true);t.tick(p.now);check(t.state()==PestExchangeTask.State.READY,"fresh complete opening role/cursor");}
 static void sent(P p,PestExchangeTask t){ready(p,t);p.now+=S;t.tick(p.now);check(p.clicks==1&&t.state()==PestExchangeTask.State.AWAITING,"single effect waits for receipt");}
 static void completed(P p,PestExchangeTask t){p.ack(true,true);t.tick(p.now);check(t.state()==PestExchangeTask.State.CLOSING,"fresh status transition and empty cursor prove acknowledgement");t.tick(p.now);check(t.state()==PestExchangeTask.State.COMPLETE&&p.closes==1&&p.session.isCurrent(p.owner)&&t.exchanged(),"close retains original root/Farm hold, one exchange");}
 public static void main(String[]args){
  var p=new P();var t=begin(p);sent(p,t);completed(p,t);
  p=new P();t=begin(p);t.tick(p.now);p.show(true,true);t.tick(p.now);t.tick(p.now);check(t.state()==PestExchangeTask.State.SKIPPED&&!t.exchanged()&&p.clicks==0&&p.closes==1,"known already-exchanged skips, never invents a transaction");
  p=new P();t=begin(p);t.tick(p.now);p.show(false,false);t.tick(p.now);check(t.state()==PestExchangeTask.State.WAIT_MENU&&p.clicks==0,"opening predictions/stale receipts are not authority");for(var s:p.menu.slots())p.items.observe(1,7,s.index(),s.item());t.tick(p.now);check(p.clicks==0&&t.state()==PestExchangeTask.State.WAIT_MENU,"opening also needs actual empty cursor");p.cursors.observe(1,7,AIR,p.now);t.tick(p.now);check(t.state()==PestExchangeTask.State.READY,"paired fresh opening admitted");
  p=new P();t=begin(p);sent(p,t);p.ack(false,false);t.tick(p.now);check(t.state()==PestExchangeTask.State.AWAITING&&p.closes==0,"local role prediction is not completion");p.items.observe(1,7,13,p.marker);t.tick(p.now);check(t.state()==PestExchangeTask.State.AWAITING,"role-only packet is not empty cursor proof");p.cursors.observe(1,7,AIR,p.now);t.tick(p.now);t.tick(p.now);check(t.state()==PestExchangeTask.State.COMPLETE,"paired later cursor proves same acknowledgement without replay");
  p=new P();t=begin(p);sent(p,t);p.inv.put(3,new ItemSnapshot(TOOL.skyblockId(),TOOL.minecraftId(),TOOL.uuid(),TOOL.name(),"emptied-vacuum",1,List.of("Ability: Vacuum RIGHT CLICK","within 10 blocks","Vacuum Bag: 0"),true));p.ack(true,true);p.items.observe(1,0,39,p.inv.get(3));t.tick(p.now);check(t.state()==PestExchangeTask.State.AWAITING,"same UUID tool metadata still requires canonical+active aliases");p.items.observe(1,7,57,p.inv.get(3));t.tick(p.now);t.tick(p.now);check(t.state()==PestExchangeTask.State.COMPLETE,"exact original UUID/range Vacuum may update captured counters with paired receipts");
  p=new P();t=begin(p);sent(p,t);p.inv.put(3,new ItemSnapshot(TOOL.skyblockId(),TOOL.minecraftId(),TOOL.uuid(),TOOL.name(),"emptied-vacuum",1,List.of("Ability: Vacuum RIGHT CLICK","within 10 blocks","Vacuum Bag: 0"),true));p.ack(true,true);p.items.observe(1,0,3,p.inv.get(3));p.items.observe(1,7,57,p.inv.get(3));t.tick(p.now);check(t.state()==PestExchangeTask.State.AWAITING&&p.closes==0,"inventoryIndex3 is not window0 hotbar raw39; wrong alias never completes");
  for(String mode:List.of("manual","world","farm","replacement","inventory","cursor","tool")){
   p=new P();t=begin(p);ready(p,t);switch(mode){case "manual"->p.manual=true;case "world"->p.ctx=new AutomationContext(2,true,true,Set.of(AutomationContext.Blocker.MENU));case "farm"->p.ctx=new AutomationContext(1,false,true,Set.of(AutomationContext.Blocker.MENU));case "replacement"->p.identity=new Object();case "inventory"->p.inv.put(42,PestBaitButtonPlanTest.bait(1));case "cursor"->p.cursor=PestBaitButtonPlanTest.bait(1);case "tool"->p.inv.put(3,PestBaitButtonPlanTest.bait(1));}t.tick(p.now);check(!t.active()&&p.clicks==0&&p.closes==0,mode+" stops before native input, no repair/close");
  }
  p=new P();p.uncertain=true;t=begin(p);sentUncertain(p,t);t.tick(p.now);check(!t.active()&&p.clicks==1&&p.closes==0,"uncertain effect is never retried/closed");
  p=new P();p.failOpen=true;t=begin(p);t.tick(p.now);t.tick(p.now);check(!t.active()&&p.opens==1&&p.closes==0,"unknown command result never retries");
  p=new P();t=begin(p);var nested=t;var f=p;p.onOpen=()->nested.tick(f.now);p.onSend=()->nested.tick(f.now);sent(p,t);completed(p,t);check(p.opens==1&&p.clicks==1,"reentrant opener/click cannot replay either effect");
  p=new P();t=begin(p);sent(p,t);p.ack(true,true);t.tick(p.now);var cancelling=t;p.onClose=cancelling::cancel;t.tick(p.now);check(t.state()==PestExchangeTask.State.CANCELLED&&p.closes==0,"cancel inside native close boundary revokes private close action");
  p=new P();t=begin(p);p.now+=21*S;t.tick(p.now);check(t.state()==PestExchangeTask.State.TIMED_OUT&&p.opens==0,"bounded root-local timeout before effects");
  p=new P();var reentrant=new PestExchangeTask(p.session,p.coordinator,p.items,p.cursors,p);var newPort=p;p.read=()->{newPort.read=()->newPort.ctx;check(reentrant.begin(newPort.owner,true,new PestIdentity.Vacuum(3,TOOL,10),newPort.now),"nested new begin accepted");throw new IllegalStateException("old observation failed after newer acceptance");};check(!reentrant.begin(p.owner,true,new PestIdentity.Vacuum(3,TOOL,10),p.now)&&reentrant.state()==PestExchangeTask.State.OPENING,"old failed read must not cancel newer accepted begin");
  p=new P();t=begin(p);sent(p,t);p.cursor=p.marker;p.ack(false,false);t.tick(p.now);check(t.state()==PestExchangeTask.State.AWAITING&&p.closes==0,"exact local GUI marker prediction is wait-only");p.cursor=AIR;completed(p,t);
  p=new P();t=begin(p);sent(p,t);p.cursor=p.marker;p.cursors.observe(1,7,p.cursor,p.now+S);p.now+=S;t.tick(p.now);check(t.state()==PestExchangeTask.State.UNCERTAIN&&p.closes==0,"server-confirmed marker cursor is never owned material or completion");
  System.out.println("PestExchangeTaskTest: PASS original-root one-shot/fresh applied role+cursor/full43/owned-vacuum proofs and cancellation; controlled ports, not live server");
 }
 static void sentUncertain(P p,PestExchangeTask t){ready(p,t);p.now+=S;t.tick(p.now);check(t.state()==PestExchangeTask.State.UNCERTAIN,"uncertain native result remains terminal");}
}
